const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/[.!?]+$/,'').replace(/\s+/g,' ');
const searchNorm=s=>norm(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const main=$('#main');
$('#nav').innerHTML=`<a href="#accueil" data-page="accueil"><span>⌂</span> Sommaire</a><a href="#verbes" data-page="verbes"><span>Aa</span> Répertoire des verbes</a>`+modules.map((m,i)=>`<a href="#${m.id}" data-page="${m.id}" class="${i===0?'nav-break':''}"><span>${m.n}</span>${m.title}</a>`).join('')+`<a class="nav-break" href="#test" data-page="test"><span>↗</span> Repères pour le test</a>`;
$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',open)};
function closeMenu(){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}
function cards(lesson='all'){
 const groups=[['01','Les temps',['present','pc','imparfait','pqp','choisir']],['02','Les pronoms',['pronoms','yen','place']],['03','Les mots utiles',['reperes','expressions']]];
 return groups.map(([number,title,ids])=>{const list=ids.map(id=>modules.find(m=>m.id===id)).filter(m=>lesson==='all'||m.lessons.includes(+lesson));return list.length?`<section class="notebook-chapter"><span class="chapter-number" aria-hidden="true">${number}</span><div class="chapter-content"><h2>${title}</h2><ul>${list.map(m=>`<li><a href="#${m.id}"><span>${m.title}</span><span aria-hidden="true">›</span></a></li>`).join('')}</ul></div></section>`:''}).join('');
}
function home(){main.innerHTML=`<div class="notebook"><header class="notebook-header"><h1>Mon carnet de français</h1><div class="notebook-meta"><span>Cours 1–8</span><label class="filter-label"><span class="sr-only">Filtrer par cours</span><select id="lesson-filter" aria-label="Filtrer par cours"><option value="all">Tous les cours</option>${Array.from({length:8},(_,i)=>`<option value="${i+1}">Cours ${i+1}</option>`).join('')}</select></label></div></header><div id="cards">${cards()}</div><a class="notebook-reference" href="#verbes"><svg viewBox="0 0 28 24" aria-hidden="true"><path d="M14 5C10 2 5 2 2 3v17c4-1 8-1 12 2 4-3 8-3 12-2V3c-3-1-8-1-12 2Zm0 0v17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><span>Répertoire des verbes<small>27 verbes · 4 temps</small></span><span aria-hidden="true">›</span></a><a class="notebook-exam" href="#test">Format et critères du test →</a></div>`;$('#lesson-filter').onchange=e=>$('#cards').innerHTML=cards(e.target.value)}
function questionHTML(q,i){return `<div class="question"><p><b>${i+1}.</b> ${esc(q[0])}</p><form class="answer-row" data-index="${i}"><input aria-label="Réponse ${i+1}" placeholder="Ta réponse…" autocomplete="off" spellcheck="false" autocapitalize="none"><button type="submit">Vérifier</button><button type="button" class="reveal">Voir la réponse</button></form><p class="feedback" aria-live="polite"></p></div>`}
function modulePage(m){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><div class="eyebrow">FICHE ${m.n} · ${m.tag.toUpperCase()}</div><h1>${m.title}</h1><p>${m.intro}</p><div class="chips">${m.lessons.map(l=>`<span class="chip">Cours ${l}</span>`).join('')}</div></header><div class="lesson-layout"><article class="lesson-body">${m.sections.map((s,i)=>`<section class="content-section" id="section-${i}"><h2>${s[0]}</h2>${s[1]}</section>`).join('')}<details lang="en"><summary>English clarification</summary><p>${m.en}</p></details>${m.q.length?`<section class="practice"><h2>Exercices</h2><p>Exercices nouveaux, inspirés des thèmes du cours. Écris avant de regarder. Les accents comptent ; majuscules et ponctuation finale sont ignorées.</p>${m.q.map(questionHTML).join('')}<p>Ces essais ne modifient pas ton suivi de progression.</p></section>`:''}<p class="source"><b>Sources et périmètre.</b> ${m.source}</p><div class="bottom-band"><a href="#${modules[(modules.indexOf(m)+1)%modules.length].id}">Fiche suivante →</a><button class="btn" onclick="window.print()">Imprimer cette fiche</button></div></article><aside class="lesson-toc"><span class="eyebrow">DANS CETTE FICHE</span>${m.sections.map((s,i)=>`<a href="#${m.id}" data-scroll="section-${i}">${s[0]}</a>`).join('')}<a href="#verbes">Répertoire des verbes ↗</a></aside></div>`;
main.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})});
main.querySelectorAll('form').forEach(f=>{const q=m.q[+f.dataset.index],input=f.querySelector('input'),feedback=f.nextElementSibling;f.onsubmit=e=>{e.preventDefault();if(!input.value.trim()){feedback.textContent='Écris une réponse avant de vérifier.';return}const ok=q[1].split('|').some(a=>norm(a)===norm(input.value));feedback.className='feedback '+(ok?'success':'review');feedback.textContent=ok?'✓ Correct. '+q[2]:'À revoir. Compare ta forme avec la règle, puis réessaie ou affiche la réponse.'};f.querySelector('.reveal').onclick=()=>{feedback.className='feedback';feedback.textContent='Réponse : '+q[1].split('|')[0]+'. '+q[2]}})}
function conjugated(v,tense){const p=v[1].split(','),reflexive=v[0]==='s’appeler';if(tense==='present')return p;if(tense==='imparfait'){if(v[0]==='être')return ['étais','étais','était','étions','étiez','étaient'];const stem=reflexive?'appel':p[3].slice(0,-3);return ['ais','ais','ait','ions','iez','aient'].map((end,i)=>{let s=stem;if(v[0]==='manger'&&(i===3||i===4))s='mang';let word=s+end;if(reflexive){const r=['m’','t’','s’','nous ','vous ','s’'][i];word=r+word}return word})}const etre=v[3]==='être';let aux=tense==='pc'?(etre?['suis','es','est','sommes','êtes','sont']:['ai','as','a','avons','avez','ont']):(etre?['étais','étais','était','étions','étiez','étaient']:['avais','avais','avait','avions','aviez','avaient']);return aux.map((a,i)=>{let pp=v[2]+(etre?(i===3||i===4||i===5?'s':''):'');if(reflexive){let r=['me ','te ','se ','nous ','vous ','se '][i];if(/^[aeé]/.test(a))r=['m’','t’','s’','nous ','vous ','s’'][i];a=r+a}return a+' '+pp})}
function verbPage(selected){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><div class="eyebrow">CONJUGAISON · COURS 1 À 8</div><h1>Conjugaison</h1><p>Les 27 verbes de la fiche du présent, déclinés dans les quatre temps de révision.</p></header><div class="verb-panel"><div class="verb-tools"><label>LE VERBE<select id="verb">${verbs.map((v,i)=>`<option value="${i}">${v[0]}</option>`).join('')}</select></label><label>LE TEMPS<select id="tense"><option value="present">Présent</option><option value="imparfait">Imparfait</option><option value="pc">Passé composé</option><option value="pqp">Plus-que-parfait</option></select></label></div><div id="verb-output"></div><details><summary>Encore des participes passés à connaître</summary><table><tr><th>Infinitif</th><th>Participe passé</th></tr>${extraParticiples.map(v=>`<tr><td>${v[0]}</td><td><b>${v[1]}</b></td></tr>`).join('')}</table><p>Liste issue du rappel du passé composé. Falloir et pleuvoir s’utilisent ici à la forme impersonnelle : il a fallu, il a plu.</p></details><details><summary>Autres participes rencontrés dans les récits et devoirs</summary><table><tr><th>Infinitif</th><th>Participe passé</th></tr>${narrativeParticiples.map(v=>`<tr><td>${v[0]}</td><td><b>${v[1]}</b></td></tr>`).join('')}</table><p>Repères tirés des exercices du cours 2, du parcours et du récit du cours 3, et du devoir 3. Le choix de l’auxiliaire dépend de la construction : elle est sortie, elle a sorti son sac ; elle s’est inscrite, elle a inscrit son nom.</p></details><p class="source">Sources : Cours 1 · verbes_frequents_indicatif_present.pdf, p. 1 ; Le passé composé RAPPEL.docx ; Cours 2 et 8 pour les règles de formation. Les tableaux aux autres temps sont générés à partir de ces règles.</p></div>`;if(selected){const i=verbs.findIndex(v=>v[0]===selected);if(i>=0)$('#verb').value=i}$('#verb').onchange=drawVerb;$('#tense').onchange=drawVerb;drawVerb()}
function drawVerb(){const v=verbs[+$('#verb').value],t=$('#tense').value,forms=conjugated(v,t),compound=['pc','pqp'].includes(t),pronouns=['je','tu','il','nous','vous','ils'];$('#verb-output').innerHTML=`<div class="verb-title"><h2>${v[0]}</h2><span class="chip">${$('#tense').selectedOptions[0].textContent}</span></div><table class="verb-table"><tbody>${forms.map((f,i)=>`<tr><td>${i===0&&/^[aeéiou]/.test(f)?'j’':pronouns[i]}</td><td><b>${f}</b></td></tr>`).join('')}</tbody></table><div class="meta-row"><div><small>Participe passé</small><b>${v[2]}</b></div><div><small>Auxiliaire</small><b>${v[3]||'avoir'}</b></div></div>${compound&&v[3]==='être'?'<div class="warning">Tableau au masculin ; nous, vous et ils au pluriel. Au féminin, ajoute e : elle est venue, elles étaient venues. Pour vous de politesse, accorde avec la personne : vous êtes venu / venue.</div>':''}${v[0]==='s’appeler'?'<p class="muted">Au passé, ces formes signifient « se nommer » (il s’est appelé Paul) ou « s’appeler l’un l’autre » (nous nous sommes appelés). Pour présenter son nom, utilise normalement le présent.</p>':''}${v[0]==='être'?'<p class="muted">Être utilise avoir aux temps composés : j’ai été, j’avais été.</p>':''}`}
function exam(){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><div class="eyebrow">EXAMEN</div><h1>Préparer le test</h1><p>Ce carnet résume les cours 1 à 8. Il ne prétend pas couvrir tout le programme ni prédire les questions du test final.</p></header><div class="exam-grid"><section><h2>Une révision en 15 min</h2><p><b>3 min :</b> rappelle une règle sans la lire.</p><p><b>5 min :</b> compare les exemples de la fiche.</p><p><b>4 min :</b> réponds aux questions puis vérifie.</p><p><b>3 min :</b> invente deux phrases dans un autre contexte.</p><a class="btn primary" href="#choisir">Commencer par les temps</a></section><section><h2>Les priorités du carnet</h2><ul><li>Former les temps et choisir le bon passé.</li><li>Connaître les verbes fréquents et leurs participes.</li><li>Choisir et placer COD, COI, y et en.</li><li>Distinguer les repères temporels.</li><li>Réutiliser ces structures dans un court récit.</li></ul><p class="muted">Priorités fondées sur les exercices du cours, pas sur une liste officielle des questions d’examen.</p></section><section><h2>Le format confirmé</h2><p><b>Écrit : 1 h 45, sur 50 points.</b> Grammaire, conjugaison, vocabulaire, lecture, rédaction et compréhension orale.</p><p><b>Oral : rendez-vous de 15 min, sur 50 points.</b> 7 min de préparation et 5 à 6 min de monologue et interaction.</p><p><b>Réussite : 60 / 100.</b> Aucun exercice d’écoute n’est intégré à ce carnet.</p></section><section><h2>Ce que l’oral demande</h2><p>Présenter un document, expliquer avantages et inconvénients, donner son opinion et des exemples, puis répondre aux questions.</p><p>La grille valorise notamment une prise de parole d’au moins 3 minutes et des idées reliées logiquement. Elle évalue aussi le vocabulaire, les structures et conjugaisons, la capacité à reformuler et une prononciation intelligible.</p><a class="btn" href="#expressions">Ouvrir le mémo de phrases</a></section></div><section class="content-section"><h2>Passer des règles à un texte</h2><details><summary>Trois tâches courtes, sans correction automatique</summary><p><b>Parcours :</b> écris au moins 100 mots sur tes études et tes expériences, puis ta situation actuelle.</p><p><b>Récit :</b> écris au moins 100 mots sur un imprévu. Installe le contexte à l’imparfait, raconte les événements au passé composé et explique un fait antérieur au plus-que-parfait si nécessaire.</p><p>Les devoirs 1 et 2 demandent 100 mots minimum ; ce seuil n’est pas une consigne confirmée pour la rédaction du test. Le devoir 2 porte sur PC / imparfait ; le plus-que-parfait est ici un prolongement des cours 7–8.</p><p><b>Lecture :</b> reprends un récit du cours. Repère qui fait quoi, les dates, la chronologie et les mots repris par les pronoms. Résume-le ensuite en trois phrases.</p><p>Relis les auxiliaires, les accords, les pronoms et les connecteurs. Ces productions libres ne sont pas évaluées par le carnet.</p></details></section><details><summary>Sources, limites et suivi</summary><p>Fondé sur french_course_syllabus_v1.md (17 octobre 2026), les fiches fournies des cours 1 à 8 et B1- EXAMEN.docx. Les explications et les exercices sont reformulés ; les compléments de référence sont signalés.</p><p>Le document d’examen donne une note globale d’oral sur 50 et une grille séparée sur 20, sans expliquer leur correspondance. Les thèmes exacts de l’examen ne sont pas confirmés.</p><p>Les points seulement annoncés dans le programme, comme le subjonctif ou le futur antérieur, ne sont pas inclus. De nouveaux cours pourront enrichir les fiches.</p><p>Les réponses ici sont des essais d’entraînement. Elles ne sont pas sauvegardées et ne mesurent pas la rétention. Le tableau de progression reste le registre des évaluations faites en séance.</p></details><p class="source">Examen : B1- EXAMEN.docx, pp. 1–4. Ce site ne contient ni enregistrement ni exercice d’écoute.</p>`}
function route(){const parts=location.hash.slice(1).split('/'),id=parts[0]||'accueil';closeMenu();$('#results').hidden=true;$('#search').value='';document.querySelectorAll('#nav a').forEach(a=>{const active=a.dataset.page===id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});let m=modules.find(x=>x.id===id);if(m)modulePage(m);else if(id==='verbes')verbPage(parts[1]?decodeURIComponent(parts[1]):null);else if(id==='test')exam();else home();document.title=(m?m.title:id==='verbes'?'Les verbes':id==='test'?'Préparer le test':'Révisions B1−')+' · Français B1−';window.scrollTo(0,0)}
$('#search').oninput=e=>{const q=searchNorm(e.target.value);const r=$('#results');if(!q){r.hidden=true;return}const matches=modules.filter(m=>searchNorm(m.title+' '+m.subtitle+' '+m.sections.map(s=>s.join(' ')).join(' ')).includes(q));const vv=verbs.filter(v=>searchNorm(v.join(' ')).includes(q));r.innerHTML=matches.slice(0,6).map(m=>`<a href="#${m.id}">${m.title}<small>${m.subtitle}</small></a>`).join('')+vv.slice(0,5).map(v=>`<a href="#verbes/${encodeURIComponent(v[0])}">${v[0]}<small>Conjugaison · participe ${v[2]}</small></a>`).join('');if(!r.innerHTML)r.innerHTML='<p>Aucun résultat. Essaie « passé », « depuis » ou « prendre ».</p>';r.hidden=false};
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#results').hidden=true;if(e.target.closest('#results a')){$('#results').hidden=true;$('#search').value=''}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();$('#results').hidden=true}});window.addEventListener('hashchange',route);route();
$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};

const installDialog = $('#install-dialog');
document.querySelectorAll('[data-install]').forEach(button=>button.onclick=()=>{closeMenu();installDialog.showModal()});
$('#close-install').onclick=()=>installDialog.close();
installDialog.addEventListener('click',e=>{if(e.target===installDialog){const r=installDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)installDialog.close()}});
